"""Populate final added text and tables from executed measurements only."""
from pathlib import Path
import sys,json,os
HERE=Path(__file__).resolve().parent;sys.path.insert(0,str(HERE.parent))
from manuscript_results import build as base_build
import numpy as np

def build():
    values,tables=base_build();cnn=json.loads((HERE/'analysis/optimized_cnn.json').read_text());noise=json.loads((HERE/'analysis/descriptor_noise.json').read_text());newclean=json.loads((HERE/'analysis/clean_new_cnn.json').read_text());assert newclean['status']=='passed'
    pending=not (HERE/'analysis/clean_replication.json').exists()
    if pending:
        assert os.environ.get('SCI_DRAFT')=='1','The full state audit must pass before final authoring.'
        clean=json.loads((HERE/'analysis/clean_numeric_replay.json').read_text());assert clean['status']=='numeric_replay_passed'
    else:
        clean=json.loads((HERE/'analysis/clean_replication.json').read_text());assert clean['status']=='passed'
    f=lambda x:f'{x:.3f}';ci=lambda x:f'{x[0]:.3f}–{x[1]:.3f}'
    c=cnn['datasets']['C_test'];e=cnn['datasets']['E_test'];p=cnn['datasets']['PH2'];g=noise['groups'][2];s=noise['groups'][1];m=noise['groups'][0]
    values['revised_abstract']=f"Purpose: To examine why stable graph propagation can coexist with failure under image noise and cohort transfer. Methods: This retrospective methodological study analyzed a controlled family of regional graph networks using finite-step perturbation bounds and frozen graph/node substitutions. Ten lesion-grouped development repetitions separated training, tuning and calibration. Evaluation used corrected DermaMNIST-C, benchmark transfer to DermaMNIST-E and source-external exploratory testing on 200 PH2 images. Additional compact convolutional references used development-only selection; a clean-installation audit checked reproducibility. Results: The implemented four-step propagation had conditional graph-perturbation coefficient 2.3616. At moderate Gaussian noise, macro F1 was 0.586 for clean inputs, 0.589 with only the graph corrupted, 0.150 with only node descriptors corrupted and 0.156 with both corrupted. Local-difference coordinates contributed {100*g['squared_perturbation_share']:.1f}% of squared standardized descriptor perturbation energy. The penalized graph did not show a reliable gain over its penalty-free control. Internal ensemble macro F1 was 0.586 for the penalized graph, {f(c['raw']['macro_f1'])} for the development-tuned compact convolutional reference and 0.649 for ResNet-18. PH2 melanoma area under the receiver operating characteristic curve was 0.507 (95% interval 0.404–0.606) for the penalized graph and 0.806 for ResNet-18. Conclusions: Conditional operator stability leaves feature construction and complete-system transfer failure unresolved. The controlled regional family exposes a measurable representation failure mechanism within the tested settings, without establishing clinical readiness, universal graph-network behavior or a superior diagnostic architecture."
    assert len(values['revised_abstract'].split())<=300
    values['descriptor_results_text']=f"The full-cohort decomposition gave standardized per-coordinate RMS changes of {m['standardized_RMS']:.3f} for RGB means, {s['standardized_RMS']:.3f} for RGB standard deviations and {g['standardized_RMS']:.3f} for local differences. Local-difference coordinates contributed {100*g['squared_perturbation_share']:.1f}% of squared standardized perturbation energy; RGB standard deviations contributed {100*s['squared_perturbation_share']:.1f}%. Position and radius did not change. The largest relative discrepancy between the ideal Gaussian expectation and the one-million-sample numerical check was {max(r['relative_error'] for r in noise['gaussian_checks']):.5f}. The energy shares are descriptor measurements, not percentages of explained classification loss."
    values['descriptor_discussion_text']=f"Two effects help explain the measured local-difference sensitivity. Absolute neighboring-pixel differences respond directly to additive noise, and division by a small training scale expands that change in standardized coordinates. Median training scales were approximately {g['training_scale_median']:.4f} for local differences, {s['training_scale_median']:.4f} for RGB standard deviations and {m['training_scale_median']:.4f} for RGB means. Raw RMS changes also differed, so standardization alone is not the whole explanation. The {100*g['squared_perturbation_share']:.1f}% descriptor-energy share and the observed learned-encoder change connect raw noise to the node path; the finite propagation bound then conditions on that changed representation. Learned encoding is nonlinear and may suppress or amplify individual coordinates. Removing difference coordinates additionally refits a different encoder, so its better noisy performance is complementary evidence rather than a direct causal percentage. Graph-only changes may preserve decisive pooled features even when many candidate edges change. These observations concern this descriptor family and tested perturbations; a learned or higher-resolution representation may fail differently."
    values['tuned_cnn_results_text']=f"The functioning development-tuned compact CNN achieved mean internal macro F1 {c['seed_mean']['macro_f1']:.3f} ± {c['seed_sd']['macro_f1']:.3f} and fixed-ensemble macro F1 {f(c['raw']['macro_f1'])} (conditional 95% interval {ci(c['ci95']['macro_f1'])}). The paired penalized-graph-minus-tuned-CNN interval was {ci(cnn['paired_C_penalized_minus_tuned_CNN_macro_f1_ci95'])}. Its ensemble did not improve on the original unaugmented CNN value of 0.604; tuning does not guarantee a test gain. This additional result evaluates the explicitly searched compact system; it does not establish that a broader optimization could not improve either architecture."
    values['tuned_cnn_external_text']=f"The additional tuned compact CNN had E macro F1 {f(e['raw']['macro_f1'])} (95% interval {ci(e['ci95']['macro_f1'])}) and PH2 MEL AUC {f(p['raw']['auc'])} (95% interval {ci(p['ci95']['auc'])}). Its PH2 seven-class argmax gave sensitivity {f(p['raw']['sensitivity'])} and specificity {f(p['raw']['specificity'])}. Its intact moderate-noise macro F1 was {f(cnn['corruption_mean']['noise_0.05']['macro_f1'])} (conditional interval {ci(cnn['corruption_mean']['noise_0.05']['macro_f1_ci95'])}). These results retain the distinction between ranking, operational decisions and image robustness."
    values['revised_conclusion']='A stable finite propagation operator did not ensure a robust dermoscopic classifier. Frozen factorial substitutions localized the major tested moderate-noise loss to node descriptors, while descriptor decomposition and training-scale measurements explained how local differences can dominate their perturbation. The penalty setting was a controlled design assumption and did not demonstrate a reliable classification gain. PH2 performance near chance was an additional complete-system transfer failure under downsampling and task/cohort shift, rather than a graph-only effect. Development-tuned compact CNN and larger image references contextualized these limits.'
    values['clean_replication_text']=f"The complete S1 package was extracted into an isolated tree and tested in a newly created Python 3.12 installation with fully pinned direct and transitive dependencies. Imported scientific module paths were verified to reside in that environment. Original PH2 images and its diagnosis table were reprocessed locally, and all 200 image hashes, counts, resized outputs and overlap checks were verified. The audit regenerated the original calibration/classwise/external bootstrap analyses and every corruption-bootstrap family, recreated official ImageNet embeddings, reran three-cohort inference for all 150 primary states, tuning inference for all 42 sensitivity states and all 23 frozen-reference corruption predictions. It compared {clean['regenerated_numeric_entries_compared']:,} regenerated numerical entries; the largest numerical difference was {clean['maximum_regenerated_numeric_error']:.2e}. The twenty compact-CNN candidates and their ten selections were additionally checked, and their test/corruption outputs and intervals were regenerated in the clean environment. Two representative original recipes and one additional compact-CNN candidate were refitted deterministically; fitted parameters agreed within the recorded tolerance. Full logs, package versions, module paths, commands, manifests and comparison reports accompany S1. This is a same-host clean-installation audit, not replication by an independent investigator or complete retraining of all 222 scientific fits. Source PH2 files and local clinical-image caches remain excluded from the delivered archive."
    if pending:values['clean_replication_text']=f"DRAFT — full saved-state audit still running. The clean-installation numerical replay compared {clean['regenerated_numeric_entries_compared']:,} regenerated entries with maximum difference {clean['maximum_regenerated_numeric_error']:.2e}. All added CNN/descriptor analyses and one representative CNN refit have passed. Final saved-state and original-recipe refit conclusions are pending; the completed reports will replace this draft paragraph before delivery."
    tables['descriptor_noise']=('Descriptor perturbations at Gaussian noise standard deviation 0.05; descriptive means over five realizations and ten training scales.',['Feature group','Coordinates','Raw RMS','Standardized RMS','Squared energy (%)'],[[r['name'],str(r['coordinates']),f(r['raw_RMS']),f(r['standardized_RMS']),f"{100*r['squared_perturbation_share']:.2f}"] for r in noise['groups']],[1.95,.8,1.0,1.45,1.4])
    cap,heads,rows,widths=tables['internal_results'];rows.append(['Development-tuned CNN']+[f"{c['seed_mean'][key]:.3f} ± {c['seed_sd'][key]:.3f}" for key in ['macro_f1','balanced_accuracy','macro_ap']]+[f(c['raw']['macro_f1']),ci(c['ci95']['macro_f1'])]);tables['internal_results']=(cap+' The added CNN uses separate within-partition tuning.',heads,rows,widths)
    cap,heads,rows,widths=tables['architectures'];rows.append(['Development-tuned CNN','Additional two-rate search; separate calibration','16,647']);tables['architectures']=(cap+' Added compact-CNN search has twenty candidate fits and ten selected states.',heads,rows,widths)
    cap,heads,rows,widths=tables['external_results'];rows.append(['Development-tuned CNN',f"{f(e['raw']['macro_f1'])}\n[{ci(e['ci95']['macro_f1'])}]",f(e['raw']['balanced_accuracy']),f"{f(p['raw']['auc'])}\n[{ci(p['ci95']['auc'])}]",f(p['raw']['sensitivity']),f(p['raw']['specificity'])]);tables['external_results']=(cap,heads,rows,widths)
    for key in ['internal_results','architectures','external_results','calibration_results','runtime_results']:
        cap,heads,rows,widths=tables[key]
        for row in rows:
            if row[0]=='MobileNetV3 Small':row[0]='MobileNetV3 fit failure'
        tables[key]=(cap,heads,rows,widths)
    tables['cnn_search']=('Compact-CNN development selection. Two rates are compared for each partition; the selected checkpoint is calibrated only afterward.',['Seed','Selected initial rate','Best epoch','Tuning macro F1','Temperature'],[[r['seed'],str(r['selected_learning_rate']),r['best_epoch'],f(r['tuning_macro_f1']),f(r['temperature'])] for r in cnn['selections']],[.7,1.6,1.0,1.8,1.5])
    (HERE/'analysis/manuscript_values.json').write_text(json.dumps({'replacements':values,'tables':tables},indent=2));return values,tables
